//! Bitmap fonts for the status screen, rendered from DejaVu Sans Mono
//! (Bitstream Vera / DejaVu licence: free to use and embed) by
//! make_font.py: ASCII, Latin-1 (so Finnish and Swedish ä, ö, å and the
//! degree sign), Latin Extended-A and common punctuation. Each glyph is
//! `w * h` alpha values of 4 bits, two per byte, row by row, high nibble
//! first. Other characters are drawn as "?".

pub struct Font {
    pub w: usize,
    pub h: usize,
    pub data: &'static [u8],
}

/// The characters included: (first, last, index of the first glyph).
const RANGES: [(u32, u32, usize); 8] = [(0x20, 0x7e, 0), (0xa0, 0xff, 95), (0x100, 0x17f, 191), (0x2013, 0x2014, 319), (0x2018, 0x201e, 321), (0x2022, 0x2022, 328), (0x2026, 0x2026, 329), (0x20ac, 0x20ac, 330)];

/// The glyph index of `c`, or of "?" if the font hasn't got it.
fn glyph(c: char) -> usize {
    let c = c as u32;
    RANGES
        .iter()
        .find(|(a, b, _)| (*a..=*b).contains(&c))
        .map_or('?' as usize - 0x20, |(a, _, base)| base + (c - a) as usize)
}

impl Font {
    /// Coverage 0..=15 of pixel (x, y) of character `c`.
    pub fn alpha(&self, c: char, x: usize, y: usize) -> u8 {
        let i = glyph(c) * self.w * self.h + y * self.w + x;
        let b = self.data[i / 2];
        if i % 2 == 0 { b >> 4 } else { b & 0x0F }
    }
}

